#!/usr/bin/env python3
import ast, base64, hashlib, json, os, shutil, sys, time
from pathlib import Path
ROOT = Path('/usr/lib/enigma2/python/Plugins/Extensions/EmbyFlowE2')
TARGET = ROOT / 'plugin.py'
HELPER = ROOT / 'embyflow_buffer_v1.py'
STATE = ROOT / 'embyflow_buffer_install_v3.json'
EXPECTED = '9f6cf0333a182d4be428d35f24f0d2d363c3339866c1c796f39be5ab3dbce835'
BRIDGE = base64.b64decode('').decode('utf8')
MODULE = base64.b64decode('')
NEEDLE = '        result = nav.playService(reference, *args, **kwargs)'
REPLACEMENT = "        play_reference = _efb_reference(reference, url)\n        state['reference'] = _efstream_ref_text(play_reference)\n        result = nav.playService(play_reference, *args, **kwargs)"

def digest(data): return hashlib.sha256(data).hexdigest()
def atomic(path, data, mode=0o644):
    temporary = Path(str(path) + '.buffer-tmp')
    with temporary.open('wb') as handle:
        handle.write(data); handle.flush(); os.fsync(handle.fileno())
    os.chmod(str(temporary), mode)
    os.replace(str(temporary), str(path))

def main():
    if '--restore' in sys.argv:
        saved = json.loads(STATE.read_text())
        if digest(TARGET.read_bytes()) != saved['installed']:
            raise RuntimeError('PY seit Testinstallation verändert. Rückweg sicher abgebrochen.')
        backup = Path(saved['backup'])
        if digest(backup.read_bytes()) != EXPECTED:
            raise RuntimeError('Sicherung stimmt nicht überein.')
        atomic(TARGET, backup.read_bytes(), saved['mode'])
        if HELPER.exists() and digest(HELPER.read_bytes()) == digest(MODULE):
            HELPER.unlink()
        STATE.unlink()
        print('Original-PY wiederhergestellt. Puffereinstellung bleibt inaktiv gespeichert.')
        return
    original = TARGET.read_bytes()
    if digest(original) != EXPECTED:
        raise RuntimeError('Andere Pluginversion: nichts installiert.')
    if HELPER.exists() or STATE.exists():
        raise RuntimeError('Puffertest-Dateien bereits vorhanden. Nichts überschrieben.')
    text = original.decode('utf8')
    start = text.index('def _efguard_play_service(nav, reference, *args, **kwargs):')
    end = text.index('\n\n_efstream_previous_player_init', start)
    section = text[start:end]
    if section.count(NEEDLE) != 1: raise RuntimeError('Einbaustelle nicht eindeutig.')
    updated = (text[:start] + section.replace(NEEDLE, REPLACEMENT) + text[end:] + BRIDGE).encode('utf8')
    ast.parse(updated.decode('utf8')); ast.parse(MODULE.decode('utf8'))
    compile(updated, str(TARGET), 'exec'); compile(MODULE, str(HELPER), 'exec')
    backup = ROOT / ('plugin_vor_PuffertestV3_' + time.strftime('%Y%m%d_%H%M%S') + '.py')
    mode = TARGET.stat().st_mode & 0o777
    shutil.copy2(str(TARGET), str(backup))
    metadata = dict(backup=str(backup), installed=digest(updated), mode=mode)
    try:
        atomic(HELPER, MODULE)
        atomic(STATE, json.dumps(metadata).encode('utf8'), 0o600)
        atomic(TARGET, updated, mode)
    except Exception:
        atomic(TARGET, original, mode)
        if HELPER.exists(): HELPER.unlink()
        if STATE.exists(): STATE.unlink()
        raise
    print('E2-Puffertest V3 installiert. Mittlere Einstellungsspalte scrollbar.')
    print('Sicherung: ' + str(backup))
    print('Erweiterte Einstellungen: mittlere Spalte nach unten. Änderungen mit Grün speichern.')

if __name__ == '__main__':
    try: main()
    except Exception as error:
        print(str(error)); sys.exit(1)
